package placement;

public class evenarray {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int[] arr = {2, 7, 4, 9, 6, 11};
		int count=0;
		for (int i =0;i<arr.length;i++) {
			if(arr[i] %2==0) {
				count++;
					
					
				}
				
			}
		System.out.print(count);
		}

	}


